  function casbahGalleryMarkup(id) {
    const image=casbahImages.find(x=>x.file.includes("black"));
    return "<div class='casbah-gallery-panel'><div class='casbah-color-switch' role='group' aria-label='Choisir le visuel du coloris'><button class='active' type='button' data-gallery-id='"+id+"' data-casbah-color='Noir' aria-pressed='true'>Noir</button><button type='button' data-gallery-id='"+id+"' data-casbah-color='Beige' aria-pressed='false'>Beige</button></div><div class='casbah-gallery-stage'><button class='casbah-gallery-arrow previous' id='"+id+"-prev' type='button' aria-label='Image précédente'>‹</button><img id='"+id+"-image' src='"+A+image.file+"' alt='"+esc(image.alt)+"'><button class='casbah-gallery-arrow next' id='"+id+"-next' type='button' aria-label='Image suivante'>›</button></div><div class='casbah-gallery-footer'><span id='"+id+"-caption'>"+esc(image.caption)+"</span><span id='"+id+"-count'>1 / 4</span></div></div>";
  }
  function initCasbahGallery(id) {
    const byColor={Noir:casbahImages.filter(x=>x.file.includes("black")),Beige:casbahImages.filter(x=>x.file.includes("beige"))};
    let color="Noir",index=0;
    const render=()=>{const item=byColor[color][index];document.getElementById(id+"-image").src=A+item.file;document.getElementById(id+"-image").alt=item.alt;document.getElementById(id+"-caption").textContent=item.caption;document.getElementById(id+"-count").textContent=(index+1)+" / "+byColor[color].length;document.querySelectorAll("[data-gallery-id='"+id+"']").forEach(button=>{const active=button.dataset.casbahColor===color;button.classList.toggle("active",active);button.setAttribute("aria-pressed",String(active));});};
    document.querySelectorAll("[data-gallery-id='"+id+"']").forEach(button=>button.addEventListener("click",()=>{color=button.dataset.casbahColor;index=0;render();}));
    document.getElementById(id+"-prev").addEventListener("click",()=>{index=(index+byColor[color].length-1)%byColor[color].length;render();});
    document.getElementById(id+"-next").addEventListener("click",()=>{index=(index+1)%byColor[color].length;render();});
  }
  function casbahStory() {
    return "<section class='section casbah-story'><div class='casbah-story-grid'><div class='casbah-story-copy'><div class='eyebrow'>COLLECTION HOUMTI · MADE BY ALGERIANS</div><h2>L’histoire d’un quartier.<br>La fierté de toute une génération.</h2><p><strong>Chaque ruelle raconte une histoire. Chaque quartier porte une identité.</strong></p><p>Issu de la <strong>COLLECTION HOUMTI de MADE BY ALGERIANS</strong>, le T-shirt Oversize CASBAH est bien plus qu’un vêtement : c’est un hommage à nos origines, à notre patrimoine et à la richesse de nos quartiers.</p><p>La COLLECTION HOUMTI puise son inspiration dans les ruelles emblématiques de notre pays, là où chaque escalier, chaque façade et chaque mur racontent une partie de notre histoire. À travers ses créations, MADE BY ALGERIANS donne une nouvelle vie à ces lieux chargés de mémoire, en transformant leur authenticité en pièces streetwear uniques et expressives.</p><p>Pour ce modèle, direction <strong>la Casbah d’Alger</strong>, véritable symbole de notre héritage culturel.</p><p>À l’avant, la signature rouge <strong>« HOUMTI »</strong> affirme subtilement ton appartenance. Dans le dos, une illustration imposante capture l’âme de la Casbah : ses escaliers de pierre, ses façades historiques et ses ruelles intemporelles.</p><p class='casbah-story-emphasis'><strong>Un design qui raconte une histoire. Une qualité qui se ressent.</strong></p><p>Confectionné en <strong>100 % coton, avec un grammage généreux de 250 g/m²</strong>, ce T-shirt se distingue par sa matière dense, sa belle tenue et son confort au quotidien.</p><p>Sa <strong>coupe oversize, ample et décontractée</strong> offre une silhouette moderne et affirmée, parfaitement ancrée dans l’univers streetwear.</p></div><aside class='casbah-story-facts'><h3>Les détails qui font la différence</h3><ul><li><span>Collection</span><strong>HOUMTI by MADE BY ALGERIANS</strong></li><li><span>Modèle</span><strong>CASBAH</strong></li><li><span>Composition</span><strong>100 % coton</strong></li><li><span>Grammage</span><strong>250 g/m² · matière épaisse et structurée</strong></li><li><span>Coupe</span><strong>Oversize, ample et décontractée</strong></li><li><span>Design avant</span><strong>Signature graphique HOUMTI rouge</strong></li><li><span>Design arrière</span><strong>Illustration artistique de la Casbah d’Alger</strong></li><li><span>Coloris</span><strong>Noir et beige</strong></li><li><span>Tailles</span><strong>S · M · L · XL</strong></li></ul><strong class='casbah-story-signature'>HOUMTI — Nos quartiers. Nos histoires. Notre fierté.</strong><p>Parce que nos rues méritent plus que des souvenirs, nous avons choisi de leur donner vie à travers nos créations.</p></aside></div></section>";
  }
