  function productDetail() {
    const q=new URLSearchParams(location.search), key=q.get("type")||"regular", n=(q.get("design")||"01").padStart(2,"0"), p=products[key]||products.regular;
    if(key==="oversize"&&q.has("collection")) { oversizeCollectionPage(p,q.get("collection")); return; }
    if(key!=="oversize"&&q.has("collection")) { productCollectionPage(p,key,q.get("collection")); return; }
    if(key==="oversize"&&q.get("design")==="bab-el-oued") { babElOuedDetail(p); return; }
    if(key==="oversize"&&q.get("design")==="casbah") { casbahDetail(p); return; }
    if(key==="oversize"&&q.get("design")==="bologhine") { bologhineDetail(p); return; }
    if(key==="oversize"&&q.get("design")==="belcourt") { belcourtDetail(p); return; }
    const facts=[["Composition",p.fabric],["Grammage",p.weight],["Coupe / format",p.fit],["Tailles",p.sizes.join(" · ")],["Coloris",p.colors],["Entretien",p.care],["Prix",money(p.price)]];
    frame("shop", "<section class='page-hero'><div class='wrap'><div class='eyebrow'>APERÇU DE LA FICHE PRODUIT</div><h1>Design "+esc(n)+" · "+esc(p.short)+"</h1><p>Fiche de présentation en préparation pour la collection MADE BY ALGERIANS.</p></div></section><div class='wrap'><div class='breadcrumbs'><a href='index.html'>Accueil</a> / <a href='boutique.html'>Boutique</a> / <a href='"+categories.find(c=>c.key===key).url+"'>"+esc(p.short)+"</a> / Design "+esc(n)+"</div><section class='section' style='padding-top:18px'><div class='product-detail'><div class='detail-visual'>"+art(false)+"</div><div class='detail-content'><div class='eyebrow'>Design "+esc(n)+" · MADE BY ALGERIANS</div><h2>"+esc(p.name)+"</h2><p class='detail-price'>"+money(p.price)+"</p><p class='lead'>"+esc(p.description)+"</p><ul class='detail-list'>"+facts.map(f=>"<li><span>"+esc(f[0])+"</span><strong>"+esc(f[1])+"</strong></li>").join("")+"</ul><div class='placeholder-alert'>Le visuel final de ce design et les photos mannequin par coloris sont encore en préparation. Cette fiche n’est pas ouverte à la commande.</div><p style='margin-top:16px'><a class='btn btn-green' href='https://wa.me/213792323644?text="+encodeURIComponent("Salam, je souhaite être informé(e) du lancement du design "+n+" sur le "+p.short)+"' target='_blank' rel='noreferrer'>Me renseigner sur ce modèle&nbsp; ↗</a></p><a class='btn btn-outline btn-small' href='"+categories.find(c=>c.key===key).url+"'>Retour aux designs</a></div></div></section></div>");
  }
